import TurndownService from 'turndown';

import { removeLineBreaks } from 'proton-mail/helpers/string';
import { extractContentFromPtag, prepareConversionToHTML } from 'proton-mail/helpers/textToHtml';

const turndownService = new TurndownService({
    bulletListMarker: '-', // Use '-' instead of '*'
    hr: '---', // Use '---' instead of '***'
    headingStyle: 'atx', // Use '#' for headings
});

turndownService.addRule('strikethrough', {
    filter: ['del', 's', 'strike' as any], // 'strike' is deprecated, however the editor insert strike tag
    replacement: function (content) {
        return `~~${content}~~`;
    },
});

// Markdown syntax cannot carry these attributes. Keep the original tag so the
// assistant can return it intact; URL restoration still verifies its message.
turndownService.addRule('formattedLinksAndImages', {
    filter: (node) =>
        ['A', 'IMG'].includes(node.nodeName) &&
        (node.hasAttribute('class') ||
            node.hasAttribute('style') ||
            (node.nodeName === 'IMG' &&
                (node.hasAttribute('proton-src') ||
                    node.hasAttribute('data-embedded-img') ||
                    node.hasAttribute('id')))),
    replacement: (_content, node) => (node as HTMLElement).outerHTML,
});

export const fixNestedLists = (dom: Document): Document => {
    dom.querySelectorAll('ul, ol').forEach((list) => {
        const parent = list.parentElement;
        if (!parent || !['UL', 'OL'].includes(parent.tagName)) {
            return;
        }

        let preceding = list.previousElementSibling;
        if (preceding?.tagName !== 'LI') {
            preceding = dom.createElement('li');
            parent.insertBefore(preceding, list);
        }
        preceding.appendChild(list);
    });
    return dom;
};

const cleanMarkdown = (markdown: string): string => {
    // Remove unnecessary spaces in list
    let result = markdown.replace(/^([ \t]*)([-*+]|\d+\.)[ \t]+/gm, (_match, indent, marker) => `${indent}${marker} `);
    // Remove unnecessary spaces in heading
    result = result.replace(/^[ \t]{1,3}(#{1,6} )/gm, '$1');
    // Remove unnecessary spaces in code block
    result = result.replace(/^[ \t]{1,3}(```)/gm, '$1');
    // Remove unnecessary spaces in blockquote
    result = result.replace(/^[ \t]{1,3}(>)/gm, '$1');
    return result;
};

export const htmlToMarkdown = (dom: Document): string => {
    const markdown = turndownService.turndown(fixNestedLists(dom));
    const markdownCleaned = cleanMarkdown(markdown);
    return markdownCleaned;
};

// Using the same config and steps than what we do in textToHTML.
// This is formatting lists and other elements correctly, adding line separators etc...
export const markdownToHTML = (markdownContent: string, keepLineBreaks = false): string => {
    const html = prepareConversionToHTML(markdownContent, ['lheading', 'heading', 'code', 'fence', 'hr'], true);
    // Need to remove line breaks, we already have <br/> tag to separate lines
    const htmlCleaned = keepLineBreaks ? html : removeLineBreaks(html);
    /**
     * The capturing group includes negative lookup "(?!<p>)" in order to avoid nested problems.
     * Ex, this capture will be ignored : "<p>Hello</p><p>Hello again</p>""
     * Because it would have ended up with this result : "Hello</p><p>Hello again"
     */
    return extractContentFromPtag(htmlCleaned) || htmlCleaned;
};
import { fixNestedLists, htmlToMarkdown, markdownToHTML } from './markdown';
import { parseModelResult } from './result';
import { replaceURLs } from './url';

describe('assistant Markdown conversion', () => {
    it('moves incorrectly nested lists into their preceding list item', () => {
        const dom = document.implementation.createHTMLDocument();
        dom.body.innerHTML = '<ul><li>Parent</li><ul><li>Child</li></ul></ul>';

        fixNestedLists(dom);

        expect(dom.body.innerHTML).toBe('<ul><li>Parent<ul><li>Child</li></ul></li></ul>');
    });

    it('keeps ordered and nested list markers through conversion', () => {
        const dom = document.implementation.createHTMLDocument();
        dom.body.innerHTML = '<ol><li>First<ul><li>Nested</li></ul></li><li>Second</li></ol>';

        const markdown = htmlToMarkdown(dom);
        const rendered = markdownToHTML(markdown);

        expect(markdown).toContain('1. First');
        expect(markdown).toContain('2. Second');
        expect(rendered).toContain('<ol>');
        expect(rendered).toContain('<ul>');
    });

    it('preserves link and image class and style across conversion', () => {
        const dom = document.implementation.createHTMLDocument();
        dom.body.innerHTML =
            '<p><a href="#1" class="link" style="color: red">Link</a><img src="#2" class="photo" style="width: 10px"></p>';

        const rendered = markdownToHTML(htmlToMarkdown(dom));

        expect(rendered).toContain('class="link"');
        expect(rendered).toContain('style="color: red"');
        expect(rendered).toContain('class="photo"');
        expect(rendered).toContain('style="width: 10px"');
    });

    it('restores only the originating message in rendered assistant HTML', () => {
        const dom = document.implementation.createHTMLDocument();
        dom.body.innerHTML =
            '<a href="https://example.com" class="link" style="color: red">Link</a><img src="https://example.com/a.png" class="photo" style="width: 10px">';
        const markdown = htmlToMarkdown(replaceURLs(dom, 'uid', 'message-1'));

        const restored = parseModelResult(markdown, 'message-1');
        const otherMessage = parseModelResult(markdown, 'message-2');

        expect(restored).toContain('https://example.com');
        expect(restored).toContain('class="link"');
        expect(restored).toContain('class="photo"');
        expect(restored).toContain('color: red');
        expect(restored).toContain('width: 10px');
        expect(otherMessage).toContain('Link');
        expect(otherMessage).not.toContain('<a');
        expect(otherMessage).not.toContain('<img');
    });
});

