            const key = `${ASSISTANT_IMAGE_PREFIX}${indexURL++}`;
            ImageURLs[key] = {
                src: srcValue,
                messageID,
                'proton-src': protonSrcValue,
                ...commonAttributes,
            };
            image.setAttribute('src', key);
        } else if (srcValue) {
            const key = `${ASSISTANT_IMAGE_PREFIX}${indexURL++}`;
            ImageURLs[key] = {
                src: srcValue,
                messageID,
                ...commonAttributes,
            };
            image.setAttribute('src', key);
